//! 🔍️ Paid signed identities, parent occurrences and consumed bits cover the complete PNG namespace.
use semio_framework_os_kernel::sqlite_snapshot::{SqliteDatabase,SqliteRow};
use semio_framework_value::{NativeDecodeControl,ValueError,ValueRefusalKind};
type Result<T>=std::result::Result<T,ValueError>;
const TABLES:&[(&str,usize,bool)]=&[("png_document",3,false),("png_literal_octet",4,true),("png_chunk",4,true),("png_ihdr",8,false),("png_palette",6,true),("png_transparency",4,true),("png_background",4,true),("png_gamma",2,false),("png_chromaticity",9,false),("png_srgb",2,false),("png_physical",4,false),("png_time",7,false),("png_stream",7,false),("png_text",7,false),("png_unknown_octet",4,true),("png_idat",3,false),("png_deflate_block",9,true),("png_deflate_code",4,true),("png_deflate_length",5,true),("png_deflate_token",7,true),("png_scanline",9,true),("png_sample",4,true),("png_packed_remainder",3,false),("png_inflated_tail",4,true)];
fn invalid(message:&str)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn sort<T>(values:&mut[T],control:&mut NativeDecodeControl<'_>,mut compare:impl FnMut(&T,&T)->Result<std::cmp::Ordering>)->Result<()>{
 fn sift<T>(values:&mut[T],mut root:usize,end:usize,control:&mut NativeDecodeControl<'_>,compare:&mut impl FnMut(&T,&T)->Result<std::cmp::Ordering>)->Result<()>{loop{control.step()?;let Some(left)=root.checked_mul(2).and_then(|at|at.checked_add(1)).filter(|at|*at<end)else{return Ok(())};let mut child=left;if left+1<end&&compare(&values[left],&values[left+1])?.is_lt(){child=left+1;}if !compare(&values[root],&values[child])?.is_lt(){return Ok(())}values.swap(root,child);root=child;}}
 for root in(0..values.len()/2).rev(){sift(values,root,values.len(),control,&mut compare)?;}for end in(1..values.len()).rev(){values.swap(0,end);sift(values,0,end,control,&mut compare)?;}Ok(())
}
struct Table<'a>{name:&'static str,identities:Vec<&'a SqliteRow>,groups:Vec<&'a SqliteRow>,used:Vec<bool>}
pub(super) struct Rows<'a>{tables:Vec<Table<'a>>}
impl<'a> Rows<'a>{
 pub fn new(database:&'a SqliteDatabase,control:&mut NativeDecodeControl<'_>)->Result<Self>{let mut tables=control.allocate_vec(TABLES.len())?;for&(name,width,grouped)in TABLES{let source=database.table(name)?;let mut identities=control.allocate_vec(source.rows.len())?;for row in&source.rows{if row.values.len()!=width||row.integer(0)?!=row.rowid{return Err(invalid("PNG row identity or column width"))}if grouped&&row.integer(2)?<0{return Err(invalid("PNG negative ordinal"))}identities.push(row);control.step()?;}sort(&mut identities,control,|a,b|Ok(a.rowid.cmp(&b.rowid)))?;for pair in identities.windows(2){if pair[0].rowid==pair[1].rowid{return Err(invalid("PNG duplicate entity identity"))}control.step()?;}let mut used=control.allocate_vec(identities.len())?;used.resize(identities.len(),false);let mut groups=control.allocate_vec(if grouped{identities.len()}else{0})?;if grouped{groups.extend_from_slice(&identities);sort(&mut groups,control,|a,b|Ok(a.integer(1)?.cmp(&b.integer(1)?).then(a.integer(2)?.cmp(&b.integer(2)?))))?;}tables.push(Table{name,identities,groups,used});}Ok(Self{tables})}
 fn table(&mut self,name:&str)->Result<&mut Table<'a>>{self.tables.iter_mut().find(|table|table.name==name).ok_or_else(||invalid("PNG semantic table absent"))}
 pub fn take(&mut self,name:&str,id:i64,control:&mut NativeDecodeControl<'_>)->Result<&'a SqliteRow>{let table=self.table(name)?;let mut first=0;let mut last=table.identities.len();while first<last{control.step()?;let middle=first+(last-first)/2;match table.identities[middle].rowid.cmp(&id){std::cmp::Ordering::Less=>first=middle+1,std::cmp::Ordering::Greater=>last=middle,std::cmp::Ordering::Equal=>{if std::mem::replace(&mut table.used[middle],true){return Err(invalid("PNG semantic entity has shared ownership"))}return Ok(table.identities[middle])}}}Err(invalid("PNG relation target absent"))}
 pub fn contains(&self,name:&str,id:i64)->bool{self.tables.iter().find(|table|table.name==name).is_some_and(|table|table.identities.binary_search_by_key(&id,|row|row.rowid).is_ok())}
 pub fn group(&mut self,name:&str,parent:i64,control:&mut NativeDecodeControl<'_>)->Result<Vec<&'a SqliteRow>>{let table=self.table(name)?;let(mut first,mut last)=(0,table.groups.len());while first<last{control.step()?;let middle=first+(last-first)/2;if table.groups[middle].integer(1)?<parent{first=middle+1}else{last=middle}}let start=first;last=table.groups.len();while first<last{control.step()?;let middle=first+(last-first)/2;if table.groups[middle].integer(1)?<=parent{first=middle+1}else{last=middle}}let mut result=control.allocate_vec(first-start)?;for row in&table.groups[start..first]{if row.integer(2)?!=i64::try_from(result.len()).map_err(|_|invalid("PNG ordinal exceeds signed64"))?{return Err(invalid("PNG occurrence ordinal is not dense"))}let at=table.identities.binary_search_by_key(&row.rowid,|row|row.rowid).map_err(|_|invalid("PNG grouped identity absent"))?;if std::mem::replace(&mut table.used[at],true){return Err(invalid("PNG occurrence has shared ownership"))}result.push(*row);control.step()?;}Ok(result)}
 pub fn finish(&self,control:&mut NativeDecodeControl<'_>)->Result<()>{for table in&self.tables{for used in&table.used{if !used{return Err(invalid("PNG orphan semantic entity"))}control.step()?;}}Ok(())}
}
